create table RB_VOUCHER_ACCT_RELATION (BASE_ACCT_NO VARCHAR(50) not null  ,PROD_TYPE VARCHAR(20) null  ,ACCT_CCY VARCHAR(3) null  ,ACCT_SEQ_NO VARCHAR(5) null  ,CARD_NO VARCHAR(19) null  ,PREFIX VARCHAR(10) null  ,DOC_TYPE VARCHAR(4) not null  ,DOC_CLASS VARCHAR(3) null  ,VOUCHER_NO VARCHAR(60) not null  ,VOUCHER_STATUS VARCHAR(3) null  ,OLD_STATUS VARCHAR(3) null  ,REFERENCE VARCHAR(60) null  ,COLLAT_IND VARCHAR(1) null  ,COLLAT_NO VARCHAR(100) null  ,CLIENT_NO VARCHAR(22) not null  ,NARRATIVE VARCHAR(600) null  ,REMARK VARCHAR(200) null  ,TRAN_DATE TIMESTAMP(3) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,CAN_REASON_CODE VARCHAR(2) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  , primary key(BASE_ACCT_NO,DOC_TYPE,VOUCHER_NO,CLIENT_NO));